@startuml

class HospitalHouseMD {}

class Patient {
  + Name : string
  + PatientID : int
}

class Doctor {
  + DoctorID : int
  + Name : string
}

class Diagnosis {
  + DiagnosisID : int
  + Description : string
}

class Treatment {
  + TreatmentID : int
  + Description : string
  + CurrentStage : int
}

class TreatmentPlan {
  + PlanID : int
}

class ConsentForm {
  + FormID : int
  + SignatureDate : date
}

enum PriorityScore {
  High
  Low
}

class Illness {
  + IllnessID : int
  + Priority : PriorityScore
}

class Nurse {
  + NurseID : int
}

HospitalHouseMD "1" -- "*" Patient
Patient "1..*" -- "1..*" Doctor
Doctor "1" -- "*" Diagnosis
Patient "1" -- "*" Diagnosis
Diagnosis "1" -- "1..*" Treatment
Illness "1" -- "*" Diagnosis
Illness "1" -- "*" Treatment
Treatment "1" -- "1" TreatmentPlan
Patient "1" -- "0..*" ConsentForm
ConsentForm "1" -- "0..*" Treatment
Doctor "1" -- "*" Treatment
Nurse "1" -- "*" Treatment

@enduml

